func encode_runs(text: String) -> String {
    var compressed = [Int]()
    var currentChar = ""
    var runLength = 0

    for char in text {
        if char == currentChar {
            runLength += 1
        } else {
            compressed.append(runLength)
            compressed.append(char)
            runLength = 1
        }
    }

    compressed.append(runLength)
    return String(compressed)
}
